#!/bin/bash
# Remove stale generated android files with old package name (app.koord)
# These get cached by EAS and cause compilation failures after a package rename.
# The correct files (app.koordinate) will be regenerated by expo prebuild.

OLD_DIR="android/app/src/main/java/app/koord"
if [ -d "$OLD_DIR" ]; then
  echo "[eas-hook] Removing stale package directory: $OLD_DIR"
  rm -rf "$OLD_DIR"
  echo "[eas-hook] Done."
else
  echo "[eas-hook] No stale directory found at $OLD_DIR"
fi
